    end
    expect(correction_entry_ids(timekeeping)).to match_array(entry_ids)
    expect(timekeeping.corrections.pluck("generation").uniq).to eq([2])
    expect(timekeeping.corrections.pluck("version").uniq).to eq([1])
  end
end

