    expect(digest).to eq(control.fetch(:load).digest)
    seeded = Company.pluck(:id)
    expect(seeded).not_to be_empty
    %w(entries reservations entry_audits).each { |table| expect(digest.fetch(table).keys).to match_array(seeded) }

